import assert from "node:assert/strict";import test from "node:test";import {FinanceService,InMemoryFinanceTransactionManager,InMemoryHoldIdempotencyStore,InMemoryHoldRepository,InMemoryInventoryReservationRepository,InMemoryLedgerIdempotencyStore,InMemoryLedgerRepository,InMemoryOrderIdempotencyStore,InMemoryOrderRepository,InMemoryPaymentEventDedupStore,InMemoryPaymentIdempotencyStore,InMemoryPaymentRepository,InMemoryRefundIdempotencyStore,InMemoryRefundRepository,InMemoryWalletRepository,type FinanceTransactionContext,type FinanceTransactionManager,type Hold,type HoldRepository,type InventoryReservation,type InventoryReservationRepository,type LedgerEntry,type LedgerIdempotencyStore,type LedgerRepository,type Order,type OrderRepository,type Payment,type PaymentRepository,type Refund,type RefundRepository,type Wallet,type WalletRepository,MockPaymentProvider} from "../src/index.ts";import {money} from "../../pricing/src/index.ts";
const setup=(ledgerStore=new InMemoryLedgerIdempotencyStore(),holdStore=new InMemoryHoldIdempotencyStore(),orderStore=new InMemoryOrderIdempotencyStore(),paymentStore=new InMemoryPaymentIdempotencyStore(),eventStore=new InMemoryPaymentEventDedupStore(),refundStore=new InMemoryRefundIdempotencyStore(),ledgerRepository=new InMemoryLedgerRepository(),walletRepository=new InMemoryWalletRepository(),holdRepository=new InMemoryHoldRepository(),orderRepository=new InMemoryOrderRepository(),paymentRepository=new InMemoryPaymentRepository(),refundRepository=new InMemoryRefundRepository(),reservationRepository=new InMemoryInventoryReservationRepository())=>{const s=new FinanceService(ledgerStore,holdStore,orderStore,paymentStore,eventStore,refundStore,ledgerRepository,walletRepository,holdRepository,orderRepository,paymentRepository,refundRepository,reservationRepository);s.createWallet({id:"w",userId:"u",currency:"BRL"});return s};
test("wallet ledger credit debit hold release capture and immutable entries",async()=>{const s=setup();await s.credit("w",money("5000","BRL"),"c");await s.credit("w",money("5000","BRL"),"c");assert.equal((await s.balance("w")).amount.toString(),"5000");const h=await s.hold("w",money("4000","BRL"),"h");assert.equal((await s.available("w")).amount.toString(),"1000");await s.release(h.id,"rel");assert.equal((await s.available("w")).amount.toString(),"5000");await s.capture((await s.hold("w",money("4000","BRL"),"h2")).id,"cap");assert.equal((await s.balance("w")).amount.toString(),"1000");await assert.rejects(s.debit("w",money("1001","BRL"),"d"),/Insufficient available balance/);assert.equal(Object.isFrozen((await s.getEntries())[0]),true)});
test("order snapshot reservation payments webhook refund and cancellation",async()=>{const s=setup();const o=await s.createOrder({id:"o",userId:"u",currency:"BRL",status:"PENDING_PAYMENT",idempotencyKey:"o",pricingSnapshotId:"snap",items:[{skinVariantId:"skin",quantity:1,unitPrice:money("10","BRL"),fees:money("0","BRL"),discount:money("0","BRL"),finalPrice:money("10","BRL"),pricingSnapshotId:"snap",source:"INVENTORY",inventoryItemId:"i"}]});assert.equal(await s.createOrder(o),o);await assert.rejects(s.reserve("i"),/Inventory unavailable/);await s.createPayment({id:"p",orderId:"o",provider:"mock",providerPaymentId:"p",amount:money("10","BRL"),status:"PENDING",idempotencyKey:"p"});const event={providerEventId:"e",paymentId:"p",type:"PAID" as const,payload:{}};assert.equal(await s.webhook(new MockPaymentProvider(),event),"PROCESSED");assert.equal(await s.webhook(new MockPaymentProvider(),event),"DUPLICATE");assert.equal((await s.getOrder("o"))?.status,"PAYMENT_CONFIRMED");assert.equal((await s.getPayment("p"))?.status,"PAID");const r=await s.refund("p",money("10","BRL"),"r");assert.equal(await s.refund("p",money("10","BRL"),"r"),r);await assert.rejects(s.refund("p",money("11","BRL"),"r2"),/Invalid refund/);assert.equal((await s.cancel("o")).status,"CANCELLED");assert.equal(o.items[0]?.pricingSnapshotId,"snap")});
test("failed payment leaves order pending",async()=>{const s=setup();await s.createOrder({id:"o",userId:"u",currency:"BRL",status:"PENDING_PAYMENT",idempotencyKey:"o",pricingSnapshotId:"x",items:[]});await s.createPayment({id:"p",orderId:"o",provider:"mock",providerPaymentId:"p",amount:money("1","BRL"),status:"PENDING",idempotencyKey:"p"});await s.webhook(new MockPaymentProvider(),{providerEventId:"f",paymentId:"p",type:"FAILED",payload:{}});assert.equal((await s.getPayment("p"))?.status,"FAILED")});
