test("shared refund repository enforces cross-service refund limits",async()=>{const orders=new InMemoryOrderRepository();const payments=new InMemoryPaymentRepository();const refunds=new InMemoryRefundRepository();const first=setup(undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,orders,payments,refunds);const second=setup(undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,orders,payments,refunds);await first.createOrder({id:"refund-limit-order",userId:"u",currency:"BRL",status:"PENDING_PAYMENT",idempotencyKey:"refund-limit-order",pricingSnapshotId:"snapshot",items:[]});await first.createPayment({id:"refund-limit-payment",orderId:"refund-limit-order",provider:"mock",providerPaymentId:"provider-payment",amount:money("100","BRL"),status:"PENDING",idempotencyKey:"refund-limit-payment"});await first.webhook(new MockPaymentProvider(),{providerEventId:"refund-limit-event",paymentId:"refund-limit-payment",type:"PAID",payload:{}});const firstRefund=await first.refund("refund-limit-payment",money("60","BRL"),"refund-limit-first");assert.equal(firstRefund.amount.amount.toString(),"60");await assert.rejects(second.refund("refund-limit-payment",money("50","BRL"),"refund-limit-over"),/Invalid refund/);assert.equal((await second.refund("refund-limit-payment",money("40","BRL"),"refund-limit-rest")).amount.amount.toString(),"40")});
