const transactionContext=():FinanceTransactionContext=>({ledgerIdempotencyStore:new InMemoryLedgerIdempotencyStore(),holdIdempotencyStore:new InMemoryHoldIdempotencyStore(),orderIdempotencyStore:new InMemoryOrderIdempotencyStore(),paymentIdempotencyStore:new InMemoryPaymentIdempotencyStore(),paymentEventDedupStore:new InMemoryPaymentEventDedupStore(),refundIdempotencyStore:new InMemoryRefundIdempotencyStore(),ledgerRepository:new InMemoryLedgerRepository(),walletRepository:new InMemoryWalletRepository(),holdRepository:new InMemoryHoldRepository(),orderRepository:new InMemoryOrderRepository(),paymentRepository:new InMemoryPaymentRepository(),refundRepository:new InMemoryRefundRepository(),inventoryReservationRepository:new InMemoryInventoryReservationRepository()});
const serviceFromContext=(context:FinanceTransactionContext,manager?:FinanceTransactionManager)=>new FinanceService(context.ledgerIdempotencyStore,context.holdIdempotencyStore,context.orderIdempotencyStore,context.paymentIdempotencyStore,context.paymentEventDedupStore,context.refundIdempotencyStore,context.ledgerRepository,context.walletRepository,context.holdRepository,context.orderRepository,context.paymentRepository,context.refundRepository,context.inventoryReservationRepository,manager);
const inventoryOrder=(id:string,key:string,itemId:string):Order=>({id,userId:"u",currency:"BRL",status:"PENDING_PAYMENT",idempotencyKey:key,pricingSnapshotId:"snapshot",items:[{skinVariantId:"skin",quantity:1,unitPrice:money("10","BRL"),fees:money("0","BRL"),discount:money("0","BRL"),finalPrice:money("10","BRL"),pricingSnapshotId:"snapshot",source:"INVENTORY",inventoryItemId:itemId}]});
const supplierOrder=(id:string,key:string):Order=>({id,userId:"u",currency:"BRL",status:"PENDING_PAYMENT",idempotencyKey:key,pricingSnapshotId:"snapshot",items:[{skinVariantId:"skin",quantity:1,unitPrice:money("10","BRL"),fees:money("0","BRL"),discount:money("0","BRL"),finalPrice:money("10","BRL"),pricingSnapshotId:"snapshot",source:"ORDER"}]});
const pendingPayment=(id:string,orderId:string):Payment=>({id,orderId,provider:"mock",providerPaymentId:`provider-${id}`,amount:money("10","BRL"),status:"PENDING",idempotencyKey:`key-${id}`});
const paidPayment=(id:string,orderId:string):Payment=>({...pendingPayment(id,orderId),status:"PAID"});
test("in-memory transaction manager returns an async callback result",async()=>{const manager=new InMemoryFinanceTransactionManager(transactionContext());assert.equal(await manager.run(async()=>"result"),"result")});
test("in-memory transaction manager exposes the supplied shared context",async()=>{const context=transactionContext();const manager=new InMemoryFinanceTransactionManager(context);await manager.run(async tx=>{assert.equal(tx.ledgerRepository,context.ledgerRepository);assert.equal(tx.paymentRepository,context.paymentRepository);assert.equal(tx.inventoryReservationRepository,context.inventoryReservationRepository)})});
test("in-memory transaction manager preserves shared state between runs",async()=>{const context=transactionContext();const manager=new InMemoryFinanceTransactionManager(context);await manager.run(async tx=>{await tx.ledgerRepository.append({id:"tx-entry",walletId:"w",type:"CREDIT",amount:money("1","BRL"),referenceType:"TEST",referenceId:"tx",idempotencyKey:"tx-entry",createdAt:new Date()})});assert.equal(await manager.run(async tx=>(await tx.ledgerRepository.listByWallet("w")).length),1)});
test("in-memory transaction manager propagates callback errors",async()=>{const manager=new InMemoryFinanceTransactionManager(transactionContext());await assert.rejects(manager.run(async()=>{throw Error("transaction failure")}),/transaction failure/)});
test("capture invokes its transaction manager exactly once",async()=>{const context=transactionContext();let calls=0;const manager:FinanceTransactionManager={async run(operation){calls++;return await operation(context)}};const service=serviceFromContext(context,manager);await service.createWallet({id:"capture-wallet",userId:"capture-user",currency:"BRL"});await service.credit("capture-wallet",money("5","BRL"),"capture-credit");const hold=await service.hold("capture-wallet",money("2","BRL"),"capture-hold");await service.capture(hold.id,"capture-entry");assert.equal(calls,1)});
test("capture uses repositories from the transaction context",async()=>{const serviceContext=transactionContext();const transactionContextB=transactionContext();const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};const service=serviceFromContext(serviceContext,manager);await transactionContextB.holdRepository.save({id:"transaction-hold",walletId:"transaction-wallet",amount:money("2","BRL"),status:"ACTIVE",idempotencyKey:"transaction-hold"});await service.capture("transaction-hold","transaction-ledger");assert.equal((await transactionContextB.holdRepository.getById("transaction-hold"))?.status,"CAPTURED");assert.equal((await transactionContextB.ledgerRepository.listAll()).length,1);assert.equal((await serviceContext.holdRepository.getById("transaction-hold")),undefined);assert.equal((await serviceContext.ledgerRepository.listAll()).length,0)});
test("capture propagates transaction manager errors",async()=>{const context=transactionContext();const manager:FinanceTransactionManager={async run(){throw Error("transaction manager unavailable")}};const service=serviceFromContext(context,manager);await assert.rejects(service.capture("missing-hold","capture-error"),/transaction manager unavailable/)});
test("capture propagates callback errors without rollback",async()=>{const serviceContext=transactionContext();const transactionContextB=transactionContext();const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};const service=serviceFromContext(serviceContext,manager);await assert.rejects(service.capture("missing-hold","capture-error"),/Hold missing/)});
test("createOrder invokes its transaction manager exactly once",async()=>{const context=transactionContext();let calls=0;const manager:FinanceTransactionManager={async run(operation){calls++;return await operation(context)}};await serviceFromContext(context,manager).createOrder(supplierOrder("transaction-order","transaction-order"));assert.equal(calls,1)});
test("createOrder uses repositories and idempotency from the transaction context",async()=>{const serviceContext=transactionContext();const transactionContextB=transactionContext();const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};const created=await serviceFromContext(serviceContext,manager).createOrder(inventoryOrder("transaction-order","transaction-order","transaction-item"));assert.equal(await transactionContextB.orderRepository.getById(created.id),created);assert.equal(await transactionContextB.orderIdempotencyStore.get(created.id),created);assert.equal((await transactionContextB.inventoryReservationRepository.getByItemId("transaction-item"))?.itemId,"transaction-item");assert.equal(await serviceContext.orderRepository.getById(created.id),undefined);assert.equal(await serviceContext.orderIdempotencyStore.get(created.id),undefined);assert.equal(await serviceContext.inventoryReservationRepository.getByItemId("transaction-item"),undefined)});
test("createOrder reserves inventory items through its real flow",async()=>{const reservations=new InMemoryInventoryReservationRepository();const service=setup(undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,reservations);await service.createOrder(inventoryOrder("reserved-order","reserved-order","reserved-item"));assert.equal((await reservations.getByItemId("reserved-item"))?.itemId,"reserved-item")});
test("createOrder blocks double-selling the same inventory item",async()=>{const service=setup();await service.createOrder(inventoryOrder("first-order","first-order","double-sell-item"));await assert.rejects(service.createOrder(inventoryOrder("second-order","second-order","double-sell-item")),/Inventory unavailable/)});
test("createOrder idempotency does not reserve an inventory item twice",async()=>{const reservations=new Map<string,InventoryReservation>();let calls=0;const repository:InventoryReservationRepository={async getByItemId(itemId){return reservations.get(itemId)},async reserve(reservation){calls++;if(reservations.has(reservation.itemId))throw Error("Inventory unavailable");reservations.set(reservation.itemId,reservation)},async release(itemId){reservations.delete(itemId)}};const service=setup(undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,repository);const order=inventoryOrder("idempotent-order","idempotent-order","idempotent-item");const created=await service.createOrder(order);assert.equal(await service.createOrder(order),created);assert.equal(calls,1)});
test("createOrder allows distinct inventory items",async()=>{const service=setup();await service.createOrder(inventoryOrder("item-a-order","item-a-order","item-a"));await assert.doesNotReject(service.createOrder(inventoryOrder("item-b-order","item-b-order","item-b")))});
test("supplier orders do not reserve inventory",async()=>{let calls=0;const repository:InventoryReservationRepository={async getByItemId(){return undefined},async reserve(){calls++},async release(){}};const service=setup(undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,undefined,repository);await service.createOrder(supplierOrder("supplier-order","supplier-order"));assert.equal(calls,0)});
test("createOrder propagates reservation errors before saving the order",async()=>{const serviceContext=transactionContext();let saved=false;const transactionContextB:FinanceTransactionContext={...transactionContext(),inventoryReservationRepository:{async getByItemId(){return undefined},async reserve(){throw Error("reservation unavailable")},async release(){}},orderRepository:{async getById(){return undefined},async save(order){saved=true;return order}}};const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};const service=serviceFromContext(serviceContext,manager);await assert.rejects(service.createOrder(inventoryOrder("failed-order","failed-order","failed-item")),/reservation unavailable/);assert.equal(saved,false);assert.equal(await transactionContextB.orderIdempotencyStore.get("failed-order"),undefined)});
test("webhook invokes its transaction manager exactly once after verification",async()=>{const context=transactionContext();await context.orderRepository.save(supplierOrder("webhook-order","webhook-order"));await context.paymentRepository.save(pendingPayment("webhook-payment","webhook-order"));let calls=0;const manager:FinanceTransactionManager={async run(operation){calls++;return await operation(context)}};const service=serviceFromContext(context,manager);assert.equal(await service.webhook(new MockPaymentProvider(),{providerEventId:"webhook-event",paymentId:"webhook-payment",type:"PAID",payload:{}}),"PROCESSED");assert.equal(calls,1)});
test("webhook uses dedup payment and order repositories from the transaction context",async()=>{const serviceContext=transactionContext();const transactionContextB=transactionContext();await transactionContextB.orderRepository.save(supplierOrder("webhook-order","webhook-order"));await transactionContextB.paymentRepository.save(pendingPayment("webhook-payment","webhook-order"));const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};const service=serviceFromContext(serviceContext,manager);await service.webhook(new MockPaymentProvider(),{providerEventId:"webhook-event",paymentId:"webhook-payment",type:"PAID",payload:{}});assert.equal(await transactionContextB.paymentEventDedupStore.has("webhook-event"),true);assert.equal((await transactionContextB.paymentRepository.getById("webhook-payment"))?.status,"PAID");assert.equal((await transactionContextB.orderRepository.getById("webhook-order"))?.status,"PAYMENT_CONFIRMED");assert.equal(await serviceContext.paymentEventDedupStore.has("webhook-event"),false);assert.equal(await serviceContext.paymentRepository.getById("webhook-payment"),undefined);assert.equal(await serviceContext.orderRepository.getById("webhook-order"),undefined)});
test("webhook verification failure avoids the transaction boundary",async()=>{const context=transactionContext();await context.orderRepository.save(supplierOrder("webhook-order","webhook-order"));await context.paymentRepository.save(pendingPayment("webhook-payment","webhook-order"));let calls=0;const manager:FinanceTransactionManager={async run(operation){calls++;return await operation(context)}};const service=serviceFromContext(context,manager);const provider={name:"invalid",async verifyWebhook(){throw Error("invalid signature")}};await assert.rejects(service.webhook(provider,{}),/invalid signature/);assert.equal(calls,0);assert.equal(await context.paymentEventDedupStore.has("webhook-event"),false);assert.equal((await context.paymentRepository.getById("webhook-payment"))?.status,"PENDING");assert.equal((await context.orderRepository.getById("webhook-order"))?.status,"PENDING_PAYMENT")});
test("webhook duplicate event does not repeat payment or order transitions",async()=>{const context=transactionContext();await context.orderRepository.save(supplierOrder("webhook-order","webhook-order"));await context.paymentRepository.save(pendingPayment("webhook-payment","webhook-order"));const service=serviceFromContext(context,new InMemoryFinanceTransactionManager(context));const event={providerEventId:"webhook-event",paymentId:"webhook-payment",type:"PAID" as const,payload:{}};assert.equal(await service.webhook(new MockPaymentProvider(),event),"PROCESSED");assert.equal(await service.webhook(new MockPaymentProvider(),event),"DUPLICATE");assert.deepEqual(service.audit,["PAYMENT_CONFIRMED"])});
test("webhook propagates transaction-context payment repository errors",async()=>{const context=transactionContext();const transactionContextB:FinanceTransactionContext={...transactionContext(),paymentRepository:{async getById(){throw Error("payment repository unavailable")},async save(payment){return payment}}};const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};await assert.rejects(serviceFromContext(context,manager).webhook(new MockPaymentProvider(),{providerEventId:"webhook-event",paymentId:"webhook-payment",type:"PAID",payload:{}}),/payment repository unavailable/)});
test("webhook propagates transaction-context order repository errors without rollback",async()=>{const context=transactionContext();const order=supplierOrder("webhook-order","webhook-order");const transactionContextB:FinanceTransactionContext={...transactionContext(),orderRepository:{async getById(){return order},async save(){throw Error("order repository unavailable")}}};await transactionContextB.paymentRepository.save(pendingPayment("webhook-payment","webhook-order"));const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};await assert.rejects(serviceFromContext(context,manager).webhook(new MockPaymentProvider(),{providerEventId:"webhook-event",paymentId:"webhook-payment",type:"PAID",payload:{}}),/order repository unavailable/);assert.equal((await transactionContextB.paymentRepository.getById("webhook-payment"))?.status,"PAID")});
test("webhook propagates transaction manager errors",async()=>{const context=transactionContext();const manager:FinanceTransactionManager={async run(){throw Error("transaction manager unavailable")}};await assert.rejects(serviceFromContext(context,manager).webhook(new MockPaymentProvider(),{providerEventId:"webhook-event",paymentId:"webhook-payment",type:"PAID",payload:{}}),/transaction manager unavailable/)});
test("refund invokes its transaction manager exactly once",async()=>{const context=transactionContext();await context.paymentRepository.save(paidPayment("refund-payment","refund-order"));let calls=0;const manager:FinanceTransactionManager={async run(operation){calls++;return await operation(context)}};await serviceFromContext(context,manager).refund("refund-payment",money("4","BRL"),"refund-key");assert.equal(calls,1)});
test("refund uses idempotency payment and refund repositories from the transaction context",async()=>{const serviceContext=transactionContext();const transactionContextB=transactionContext();await transactionContextB.paymentRepository.save(paidPayment("refund-payment","refund-order"));const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};const refund=await serviceFromContext(serviceContext,manager).refund("refund-payment",money("4","BRL"),"refund-key");assert.equal(await transactionContextB.refundIdempotencyStore.get("refund-key"),refund);assert.equal(await transactionContextB.refundRepository.getById(refund.id),refund);assert.equal((await transactionContextB.paymentRepository.getById("refund-payment"))?.status,"PAID");assert.equal(await serviceContext.refundIdempotencyStore.get("refund-key"),undefined);assert.equal(await serviceContext.refundRepository.getById(refund.id),undefined);assert.equal(await serviceContext.paymentRepository.getById("refund-payment"),undefined)});
test("refund idempotency returns the original refund without a second save",async()=>{const context=transactionContext();await context.paymentRepository.save(paidPayment("refund-payment","refund-order"));let saves=0;const refunds=new Map<string,Refund>();const transactionContextB:FinanceTransactionContext={...context,refundRepository:{async getById(id){return refunds.get(id)},async save(refund){saves++;refunds.set(refund.id,refund);return refund},async listByPayment(paymentId){return [...refunds.values()].filter(refund=>refund.paymentId===paymentId)},async count(){return refunds.size}}};const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};const service=serviceFromContext(context,manager);const first=await service.refund("refund-payment",money("4","BRL"),"refund-key");assert.equal(await service.refund("refund-payment",money("4","BRL"),"refund-key"),first);assert.equal(saves,1);assert.deepEqual(service.audit,["REFUND_COMPLETED"])});
test("refund propagates transaction-context payment repository errors",async()=>{const context=transactionContext();const transactionContextB:FinanceTransactionContext={...transactionContext(),paymentRepository:{async getById(){throw Error("payment repository unavailable")},async save(payment){return payment}}};const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};await assert.rejects(serviceFromContext(context,manager).refund("refund-payment",money("4","BRL"),"refund-key"),/payment repository unavailable/)});
test("refund propagates transaction-context refund repository errors",async()=>{const context=transactionContext();const transactionContextB:FinanceTransactionContext={...transactionContext(),refundRepository:{async getById(){return undefined},async save(refund){return refund},async listByPayment(){throw Error("refund repository unavailable")},async count(){return 0}}};await transactionContextB.paymentRepository.save(paidPayment("refund-payment","refund-order"));const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};await assert.rejects(serviceFromContext(context,manager).refund("refund-payment",money("4","BRL"),"refund-key"),/refund repository unavailable/)});
test("refund propagates transaction-context idempotency store errors without rollback",async()=>{const context=transactionContext();const transactionContextB:FinanceTransactionContext={...transactionContext(),refundIdempotencyStore:{async get(){return undefined},async set(){throw Error("refund idempotency unavailable")}}};await transactionContextB.paymentRepository.save(paidPayment("refund-payment","refund-order"));const manager:FinanceTransactionManager={async run(operation){return await operation(transactionContextB)}};await assert.rejects(serviceFromContext(context,manager).refund("refund-payment",money("4","BRL"),"refund-key"),/refund idempotency unavailable/);assert.equal((await transactionContextB.refundRepository.listByPayment("refund-payment")).length,1)});
