test("FinanceService awaits a custom async ledger idempotency store",async()=>{let stored:LedgerEntry|undefined;const store:LedgerIdempotencyStore={async get(){await Promise.resolve();return stored},async set(_key,entry){await Promise.resolve();stored=entry}};const service=setup(store);const entry=await service.credit("w",money("1","BRL"),"custom-async");assert.equal(stored,entry);assert.equal(await service.credit("w",money("1","BRL"),"custom-async"),entry)});
